        public Func<SourceWorkAuthorization, SourceWorkAuthorization>? ChangeAuth;
        public Func<SourceWorkTransactionReceipt, SourceWorkTransactionReceipt>? ChangeReceipt;
        public Func<Task>? BeforeAuth;
        public JsonObject? Existing, Written;
        public string? SeenCollection; public bool SeenOwnPublic; public int Transactions;
        public IReadOnlyList<JsonObject> FetchRows = [];
        public async Task<SourceWorkAuthorization> AuthorizeAsync(SyncScope scope, SyncTable table, string? id, bool write, CancellationToken ct)
        {
            if (BeforeAuth is not null) await BeforeAuth(); ct.ThrowIfCancellationRequested();
            var auth = new SourceWorkAuthorization(scope.UserId, scope.ProjectId, "synthetic-firebase-uid", "synthetic-person-id", "Source fixture", "user", DateTimeOffset.UtcNow.AddMinutes(1)); return ChangeAuth?.Invoke(auth) ?? auth;
        }
        public Task<SourceWorkTransactionReceipt> TransactAsync(string collection, string id, string revision, SourceWorkAuthorization auth, Func<JsonObject?, JsonObject?> transform, CancellationToken ct)
        {
            ct.ThrowIfCancellationRequested(); Transactions++; SeenCollection = collection; Written = transform(Existing is null ? null : (JsonObject)Existing.DeepClone());
            var receipt = new SourceWorkTransactionReceipt(collection, id, revision, true); return Task.FromResult(ChangeReceipt?.Invoke(receipt) ?? receipt);
        }
        public Task<SourceWorkFetch> FetchAsync(string collection, bool publicOrOwnTasks, SourceWorkAuthorization authorization, CancellationToken ct) { SeenCollection = collection; SeenOwnPublic = publicOrOwnTasks; return Task.FromResult(new SourceWorkFetch(FetchRows, true)); }
    }
    static JsonObject NativeFields(string kind = "projects", string? project = null) => new() { ["format"] = "jindan-native-work-record/1", ["kind"] = kind, ["projectId"] = project, ["revision"] = 1, ["fields"] = new JsonObject { ["title"] = "Synthetic work", ["content"] = "Synthetic content", ["startDate"] = "2026-11-05", ["endDate"] = "2026-11-05" } };
    static SyncEnvelope Envelope(SyncTable table = SyncTable.Projects, JsonObject? fields = null) => new(new("local-only-user", "synthetic-project"), new(table, "synthetic-project", SyncOperation.Upsert, Guid.NewGuid().ToString("N"), DateTimeOffset.UtcNow), new("synthetic-project", "local-only-user", fields ?? NativeFields()));
    static async Task SyncExpect(string code, Func<Task> action) { try { await action(); } catch (SyncException e) { Check(e.Code == code, "Expected " + code + ", got " + e.Code); return; } throw new Exception("Expected " + code); }
